	-- Dark Convent subtype -> its lore icon, its lore's name and its spells (icon and tooltip)
	lores = {
		corv_dc_wh2_dlc10_def_sorceress_beasts = { icon = "ui/campaign ui/agents/wh_dlc03_lore_beasts.png", group = "Lore of Beasts", spells = { { icon = "ui/battle ui/ability_icons/wh_dlc03_lore_passive_wild_heart.png", tip = "Wild Heart||Amber is the colour of beasts. Such magic can ensnare and entrap animals much more easily than so-called \"intelligent\" species." }, { icon = "ui/battle ui/ability_icons/wh_dlc03_spell_beasts_flock_of_doom.png", tip = "Flock of Doom||With a mighty bellow, the spellcaster invokes Corvus the Crow Lord, summoning his servants to peck at the foe's eyes." }, { icon = "ui/battle ui/ability_icons/wh_dlc03_spell_beasts_panns_impenetrable_pelt.png", tip = "Pann's Impenetrable Pelt||Calling upon the beast-spirits of the wild, the caster sheathes vulnerable flesh in unyielding fur and hide." }, { icon = "ui/battle ui/ability_icons/wh_dlc03_spell_beasts_the_amber_spear.png", tip = "The Amber Spear||Sounding a gnarled horn, the caster summons a glowing amber spear and hurls it at the foe with uncanny accuracy." }, { icon = "ui/battle ui/ability_icons/wh_dlc03_spell_beasts_the_curse_of_anraheir.png", tip = "The Curse of Anraheir||At the spellcaster's command, nebulous nature spirits assail the foe, clawing with hands not nearly as insubstantial as they first appear." }, { icon = "ui/battle ui/ability_icons/wh_dlc03_spell_beasts_transformation_of_kadon.png", tip = "Transformation of Kadon||Kadon was able to shift his shape to that of any monster, even a Manticore. One day he found he could not change back..." }, { icon = "ui/battle ui/ability_icons/wh_dlc03_spell_beasts_wyssans_wildform.png", tip = "Wyssan's Wildform||The spellcaster unleashes the beast within, using its fury to transform allies into bestial forms." } } },
		corv_dc_wh2_dlc10_def_sorceress_death = { icon = "ui/campaign ui/agents/wh_main_lore_death.png", group = "Lore of Death", spells = { { icon = "ui/battle ui/ability_icons/wh_main_lore_passive_life_leeching.png", tip = "Life Leeching||Spellcasters who practise Death Magic can channel the life force of foes into their spells." }, { icon = "ui/battle ui/ability_icons/wh_main_spell_death_aspect_of_the_dreadknight.png", tip = "Aspect of the Dread Knight||An invisible aura of horror surrounds the Wizard’s allies. Only the bravest foes now stand before them." }, { icon = "ui/battle ui/ability_icons/wh_main_spell_death_doom_and_darkness.png", tip = "Doom & Darkness||Spirits of the departed assail the Wizard’s foes, sapping their resolve and causing dread among their numbers." }, { icon = "ui/battle ui/ability_icons/wh_main_spell_death_soulblight.png", tip = "Soulblight||Harnessing the sickly power of Shyish, the Wizard weakens the foe's will to survive the battle." }, { icon = "ui/battle ui/ability_icons/wh_main_spell_death_spirit_leech.png", tip = "Spirit Leech||The Wizard extends an ebon hand towards the chosen foe, leeching its spirit through tainted sorcery." }, { icon = "ui/battle ui/ability_icons/wh_main_spell_death_the_fate_of_bjuna.png", tip = "The Fate of Bjuna||Following the fate of the unsmiling warrior, Bjuna, the targets of the caster’s ire will laugh themselves to death." }, { icon = "ui/battle ui/ability_icons/wh_main_spell_death_the_purple_sun_of_xereus.png", tip = "The Purple Sun of Xereus||A colossal orb of purple-edged darkness materialises - those who do not escape its crystalline touch are doomed for eternity!" } } },
		corv_dc_wh2_dlc10_def_supreme_sorceress_beasts = { icon = "ui/campaign ui/agents/wh_dlc03_lore_beasts.png", group = "Lore of Beasts", spells = { { icon = "ui/battle ui/ability_icons/wh_dlc03_lore_passive_wild_heart.png", tip = "Wild Heart||Amber is the colour of beasts. Such magic can ensnare and entrap animals much more easily than so-called \"intelligent\" species." }, { icon = "ui/battle ui/ability_icons/wh_dlc03_spell_beasts_flock_of_doom.png", tip = "Flock of Doom||With a mighty bellow, the spellcaster invokes Corvus the Crow Lord, summoning his servants to peck at the foe's eyes." }, { icon = "ui/battle ui/ability_icons/wh_dlc03_spell_beasts_panns_impenetrable_pelt.png", tip = "Pann's Impenetrable Pelt||Calling upon the beast-spirits of the wild, the caster sheathes vulnerable flesh in unyielding fur and hide." }, { icon = "ui/battle ui/ability_icons/wh_dlc03_spell_beasts_the_amber_spear.png", tip = "The Amber Spear||Sounding a gnarled horn, the caster summons a glowing amber spear and hurls it at the foe with uncanny accuracy." }, { icon = "ui/battle ui/ability_icons/wh_dlc03_spell_beasts_the_curse_of_anraheir.png", tip = "The Curse of Anraheir||At the spellcaster's command, nebulous nature spirits assail the foe, clawing with hands not nearly as insubstantial as they first appear." }, { icon = "ui/battle ui/ability_icons/wh_dlc03_spell_beasts_transformation_of_kadon.png", tip = "Transformation of Kadon||Kadon was able to shift his shape to that of any monster, even a Manticore. One day he found he could not change back..." }, { icon = "ui/battle ui/ability_icons/wh_dlc03_spell_beasts_wyssans_wildform.png", tip = "Wyssan's Wildform||The spellcaster unleashes the beast within, using its fury to transform allies into bestial forms." } } },
		corv_dc_wh2_dlc10_def_supreme_sorceress_dark = { icon = "ui/campaign ui/agents/wh2_main_lore_dark_magic.png", group = "Lore of Dark Magic", spells = { { icon = "ui/battle ui/ability_icons/wh2_main_lore_passive_spiteful_conjuration.png", tip = "Spiteful Conjuration||An aura of Dark Magic conjures black darts of malice that flit through the air to pierce victims of the spellcaster’s spite." }, { icon = "ui/battle ui/ability_icons/wh2_main_spell_dark_magic_bladewind.png", tip = "Bladewind||A swirling maelstrom of swords spin and slash their way across the battlefield in search of blood." }, { icon = "ui/battle ui/ability_icons/wh2_main_spell_dark_magic_chillwind.png", tip = "Chillwind||A freezing gale is conjured and sent to assail the target with ice and hail." }, { icon = "ui/battle ui/ability_icons/wh2_main_spell_dark_magic_doombolt.png", tip = "Doombolt||The sky opens and a bolt of burning, pure Chaos black lightning hurtles towards the foe." }, { icon = "ui/battle ui/ability_icons/wh2_main_spell_dark_magic_power_of_darkness.png", tip = "Power of Darkness||The caster draws on unstable power from the Realm of Chaos to charge their spells." }, { icon = "ui/battle ui/ability_icons/wh2_main_spell_dark_magic_soul_stealer.png", tip = "Soul Stealer||Tendrils of solidified darkness writhe outwards, draining the lifeforce from foes and renewing the caster’s own vigour." }, { icon = "ui/battle ui/ability_icons/wh2_main_spell_dark_magic_word_of_pain.png", tip = "Word of Pain||As the caster utters a forbidden name, their enemies are wracked with waves of agony." } } },
		corv_dc_wh2_dlc10_def_supreme_sorceress_death = { icon = "ui/campaign ui/agents/wh_main_lore_death.png", group = "Lore of Death", spells = { { icon = "ui/battle ui/ability_icons/wh_main_lore_passive_life_leeching.png", tip = "Life Leeching||Spellcasters who practise Death Magic can channel the life force of foes into their spells." }, { icon = "ui/battle ui/ability_icons/wh_main_spell_death_aspect_of_the_dreadknight.png", tip = "Aspect of the Dread Knight||An invisible aura of horror surrounds the Wizard’s allies. Only the bravest foes now stand before them." }, { icon = "ui/battle ui/ability_icons/wh_main_spell_death_doom_and_darkness.png", tip = "Doom & Darkness||Spirits of the departed assail the Wizard’s foes, sapping their resolve and causing dread among their numbers." }, { icon = "ui/battle ui/ability_icons/wh_main_spell_death_soulblight.png", tip = "Soulblight||Harnessing the sickly power of Shyish, the Wizard weakens the foe's will to survive the battle." }, { icon = "ui/battle ui/ability_icons/wh_main_spell_death_spirit_leech.png", tip = "Spirit Leech||The Wizard extends an ebon hand towards the chosen foe, leeching its spirit through tainted sorcery." }, { icon = "ui/battle ui/ability_icons/wh_main_spell_death_the_fate_of_bjuna.png", tip = "The Fate of Bjuna||Following the fate of the unsmiling warrior, Bjuna, the targets of the caster’s ire will laugh themselves to death." }, { icon = "ui/battle ui/ability_icons/wh_main_spell_death_the_purple_sun_of_xereus.png", tip = "The Purple Sun of Xereus||A colossal orb of purple-edged darkness materialises - those who do not escape its crystalline touch are doomed for eternity!" } } },
		corv_dc_wh2_dlc10_def_supreme_sorceress_fire = { icon = "ui/campaign ui/agents/wh_main_lore_fire.png", group = "Lore of Fire", spells = { { icon = "ui/battle ui/ability_icons/wh_main_lore_passive_kindleflame.png", tip = "Kindleflame||Fire feeds fire, two blazes together are stronger and hotter than two apart. The Kindleflame intensifies such fire.  " }, { icon = "ui/battle ui/ability_icons/wh_main_spell_fire_cascading_fire_cloak.png", tip = "Cascading Fire Cloak||A blazing aura surrounds the Pyromancer's chosen ally, shielding them with protective flame and augmenting their abilities." }, { icon = "ui/battle ui/ability_icons/wh_main_spell_fire_fireball.png", tip = "Fireball||The Wizard conjures a boiling ball of magical flame and hurls it at a nearby foe." }, { icon = "ui/battle ui/ability_icons/wh_main_spell_fire_flame_storm.png", tip = "Flame Storm||Conjured by a Bright Wizard or Chaos Sorcerer, a column of churning fire erupts from the battlefield, causing much destruction!    " }, { icon = "ui/battle ui/ability_icons/wh_main_spell_fire_flaming_sword_of_rhuin.png", tip = "Flaming Sword of Rhuin||The Wizard ensorcels allied weapons, making them burn with a savage fire. The targets of the spell are augmented with superior flaming blades." }, { icon = "ui/battle ui/ability_icons/wh_main_spell_fire_piercing_bolts_of_burning.png", tip = "Piercing Bolts of Burning||Focusing all his mystical might, the Pyromancer strikes the foe with a flurry of incandescent missiles." }, { icon = "ui/battle ui/ability_icons/wh_main_spell_fire_the_burning_head.png", tip = "The Burning Head||A cackling, flaming visage appears before the Wizard. With a gleeful screech, it swirls around the battlefield, immolating anything in its way.  " } } },
		corv_dc_wh2_dlc10_def_supreme_sorceress_shadow = { icon = "ui/campaign ui/agents/wh_dlc05_lore_shadow.png", group = "Lore of Shadows", spells = { { icon = "ui/battle ui/ability_icons/wh_dlc05_lore_passive_smoke_and_mirrors.png", tip = "Smoke & Mirrors||A conjured shadow is just as obfuscating as a real one - the Shadow Wizard is master or mistress of the 'concealing' arts." }, { icon = "ui/battle ui/ability_icons/wh_dlc05_spell_shadow_melkoths_mystifying_miasma.png", tip = "Melkoth's Mystifying Miasma||The caster weaves a confounding fog that numbs and deludes enemies, causing them to stumble and stagger." }, { icon = "ui/battle ui/ability_icons/wh_dlc05_spell_shadow_okkams_mindrazor.png", tip = "Okkam's Mindrazor||The supernatural solution is often the best; weapons materialise in hands, allowing them to slice through flesh, soul, and consciousness." }, { icon = "ui/battle ui/ability_icons/wh_dlc05_spell_shadow_pit_of_shades.png", tip = "Pit of Shades||The spellcaster opens a vortex leading into the Pit. Anything caught within it will be lost forever." }, { icon = "ui/battle ui/ability_icons/wh_dlc05_spell_shadow_the_enfeebling_foe.png", tip = "The Enfeebling Foe||When cast, this spell enfeebles enemy minds; they feel the crushing weight of reality bearing down upon them." }, { icon = "ui/battle ui/ability_icons/wh_dlc05_spell_shadow_the_penumbral_pendulum.png", tip = "The Penumbral Pendulum||A spectral pendulum is summoned by the Wizard. On command, it swings, razor sharp and with lethal speed, through the foe." }, { icon = "ui/battle ui/ability_icons/wh_dlc05_spell_shadow_the_withering.png", tip = "The Withering||The Wizard destroys the foe from within, corroding their minds with doubt and crisis." } } },
