		corv_dc_wh2_main_def_sorceress_fire = { icon = "ui/campaign ui/agents/wh_main_lore_fire.png", group = "Lore of Fire", spells = { { icon = "ui/battle ui/ability_icons/wh_main_lore_passive_kindleflame.png", tip = "Kindleflame||Fire feeds fire, two blazes together are stronger and hotter than two apart. The Kindleflame intensifies such fire.  " }, { icon = "ui/battle ui/ability_icons/wh_main_spell_fire_cascading_fire_cloak.png", tip = "Cascading Fire Cloak||A blazing aura surrounds the Pyromancer's chosen ally, shielding them with protective flame and augmenting their abilities." }, { icon = "ui/battle ui/ability_icons/wh_main_spell_fire_fireball.png", tip = "Fireball||The Wizard conjures a boiling ball of magical flame and hurls it at a nearby foe." }, { icon = "ui/battle ui/ability_icons/wh_main_spell_fire_flame_storm.png", tip = "Flame Storm||Conjured by a Bright Wizard or Chaos Sorcerer, a column of churning fire erupts from the battlefield, causing much destruction!    " }, { icon = "ui/battle ui/ability_icons/wh_main_spell_fire_flaming_sword_of_rhuin.png", tip = "Flaming Sword of Rhuin||The Wizard ensorcels allied weapons, making them burn with a savage fire. The targets of the spell are augmented with superior flaming blades." }, { icon = "ui/battle ui/ability_icons/wh_main_spell_fire_piercing_bolts_of_burning.png", tip = "Piercing Bolts of Burning||Focusing all his mystical might, the Pyromancer strikes the foe with a flurry of incandescent missiles." }, { icon = "ui/battle ui/ability_icons/wh_main_spell_fire_the_burning_head.png", tip = "The Burning Head||A cackling, flaming visage appears before the Wizard. With a gleeful screech, it swirls around the battlefield, immolating anything in its way.  " } } },
		corv_dc_wh2_main_def_sorceress_shadow = { icon = "ui/campaign ui/agents/wh_dlc05_lore_shadow.png", group = "Lore of Shadows", spells = { { icon = "ui/battle ui/ability_icons/wh_dlc05_lore_passive_smoke_and_mirrors.png", tip = "Smoke & Mirrors||A conjured shadow is just as obfuscating as a real one - the Shadow Wizard is master or mistress of the 'concealing' arts." }, { icon = "ui/battle ui/ability_icons/wh_dlc05_spell_shadow_melkoths_mystifying_miasma.png", tip = "Melkoth's Mystifying Miasma||The caster weaves a confounding fog that numbs and deludes enemies, causing them to stumble and stagger." }, { icon = "ui/battle ui/ability_icons/wh_dlc05_spell_shadow_okkams_mindrazor.png", tip = "Okkam's Mindrazor||The supernatural solution is often the best; weapons materialise in hands, allowing them to slice through flesh, soul, and consciousness." }, { icon = "ui/battle ui/ability_icons/wh_dlc05_spell_shadow_pit_of_shades.png", tip = "Pit of Shades||The spellcaster opens a vortex leading into the Pit. Anything caught within it will be lost forever." }, { icon = "ui/battle ui/ability_icons/wh_dlc05_spell_shadow_the_enfeebling_foe.png", tip = "The Enfeebling Foe||When cast, this spell enfeebles enemy minds; they feel the crushing weight of reality bearing down upon them." }, { icon = "ui/battle ui/ability_icons/wh_dlc05_spell_shadow_the_penumbral_pendulum.png", tip = "The Penumbral Pendulum||A spectral pendulum is summoned by the Wizard. On command, it swings, razor sharp and with lethal speed, through the foe." }, { icon = "ui/battle ui/ability_icons/wh_dlc05_spell_shadow_the_withering.png", tip = "The Withering||The Wizard destroys the foe from within, corroding their minds with doubt and crisis." } } },
